import datetime


def next_billing_date(start: datetime.date, months_ahead: int) -> datetime.date:
    if not isinstance(months_ahead, int):
        raise TypeError("months_ahead must be an int")
    new_year = start.year + (start.month - 1 + months_ahead) // 12
    new_month = (start.month - 1 + months_ahead) % 12 + 1
    if new_month == 12:
        last_day = 31
    else:
        last_day = (datetime.date(new_year, new_month + 1, 1) -
                    datetime.timedelta(days=1)).day
    new_day = min(start.day, last_day)
    return datetime.date(new_year, new_month, new_day)
